var LiteSlider=(function(){function init(id,cfg){var stage=document.getElementById(id);if(!stage)return;var track=stage.querySelector('.ls-track');var els=Array.prototype.slice.call(stage.querySelectorAll('.ls-slide'));var btnP=stage.querySelector('.ls-prev');var btnN=stage.querySelector('.ls-next');var barFill=stage.querySelector('.ls-bar-fill');var total=cfg.total||els.length;var ivl=cfg.interval||4000;var playing=cfg.autoplay!==false;var mode=cfg.mode||'slide';var spd=cfg.speed||600;var ph=cfg.pauseHover!==false;var loop=cfg.loop!==false;var cur=Math.min(cfg.startSlide||0,total-1);var prev=-1,timer=null,sx=0,busy=false;stage.classList.add('ls-mode-'+mode);track.style.cssText='position:absolute;top:0;right:0;bottom:0;left:0;';els.forEach(function(s,i){s.style.cssText='position:absolute;top:0;right:0;bottom:0;left:0;display:block;overflow:hidden;will-change:transform;';if(mode==='fade'){s.style.transform='none';s.style.opacity=(i===cur)?'1':'0';s.style.transition='opacity '+spd+'ms ease';s.style.pointerEvents=(i===cur)?'auto':'none';}else{s.style.transform='translateX('+(i===cur?'0':'100')+'%)';s.style.opacity='1';}});function go(n,dir){if(busy)return;if(!loop){if(n>=total&&dir>0)return;if(n<0&&dir<0)return;}
prev=cur;cur=((n%total)+total)%total;if(cur===prev)return;mode==='fade'?doFade():doSlide(dir);resetBar();}
function doFade(){busy=true;els[cur].style.zIndex='2';els[prev].style.zIndex='1';els[cur].style.transition='opacity '+spd+'ms ease';els[prev].style.transition='opacity '+spd+'ms ease';els[cur].style.opacity='1';els[cur].style.pointerEvents='auto';els[prev].style.opacity='0';els[prev].style.pointerEvents='none';setTimeout(function(){els[prev].style.zIndex='';els[cur].style.zIndex='';busy=false;},spd+50);}
function doSlide(dir){var d=(dir!==undefined)?dir:(cur>prev?1:-1);busy=true;els[cur].style.transition='none';els[cur].style.transform='translateX('+(d*100)+'%)';els[cur].style.zIndex='2';els[prev].style.zIndex='1';void els[cur].getBoundingClientRect();var ease='transform '+spd+'ms cubic-bezier(.4,0,.2,1)';els[cur].style.transition=ease;els[prev].style.transition=ease;els[cur].style.transform='translateX(0%)';els[prev].style.transform='translateX('+(-d*100)+'%)';setTimeout(function(){els[prev].style.transition='none';els[prev].style.transform='translateX(100%)';els[prev].style.zIndex='';els[cur].style.zIndex='';busy=false;},spd+50);}
function resetBar(){if(!barFill)return;barFill.style.transition='none';barFill.style.width='0%';if(playing){requestAnimationFrame(function(){requestAnimationFrame(function(){barFill.style.transition='width '+ivl+'ms linear';barFill.style.width='100%';});});}}
function startAuto(){clearInterval(timer);timer=setInterval(function(){go(cur+1,1);},ivl);resetBar();}
function stopAuto(){clearInterval(timer);if(barFill){barFill.style.transition='none';barFill.style.width='0%';}}
if(btnP)btnP.addEventListener('click',function(e){e.stopPropagation();go(cur-1,-1);if(playing)startAuto();});if(btnN)btnN.addEventListener('click',function(e){e.stopPropagation();go(cur+1,1);if(playing)startAuto();});if(ph){stage.addEventListener('mouseenter',function(){if(playing)stopAuto();});stage.addEventListener('mouseleave',function(){if(playing)startAuto();});}
var touchStartX=0,touchStartY=0;stage.addEventListener('touchstart',function(e){touchStartX=e.touches[0].clientX;touchStartY=e.touches[0].clientY;},{passive:true});stage.addEventListener('touchend',function(e){var dx=e.changedTouches[0].clientX-touchStartX;var dy=e.changedTouches[0].clientY-touchStartY;if(Math.abs(dx)>Math.abs(dy)&&Math.abs(dx)>40){var d=dx<0?1:-1;go(cur+d,d);if(playing)startAuto();}},{passive:true});var mouseDown=false;stage.addEventListener('mousedown',function(e){mouseDown=true;sx=e.clientX;});stage.addEventListener('mouseup',function(e){if(!mouseDown)return;mouseDown=false;var dx=e.clientX-sx;if(Math.abs(dx)>40){var d=dx<0?1:-1;go(cur+d,d);if(playing)startAuto();}});stage.addEventListener('mouseleave',function(){mouseDown=false;});stage.setAttribute('tabindex','0');stage.addEventListener('keydown',function(e){if(e.key==='ArrowLeft'){go(cur-1,-1);if(playing)startAuto();}
if(e.key==='ArrowRight'){go(cur+1,1);if(playing)startAuto();}});if(playing)startAuto();}
return{init:init};})();
